WITH ranked AS (
  SELECT order_id, customer_id,
    ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY amount DESC) AS rn
  FROM `sales.orders`
)
SELECT order_id FROM ranked WHERE rn = 1;

SELECT order_id, attrs.channel AS channel
FROM `sales.orders`
WHERE attrs.channel = "web";

SELECT table_name, row_count, size_bytes
FROM `sales.INFORMATION_SCHEMA.TABLES`
WHERE table_name = "orders";

SELECT order_id, customer_id
FROM `sales.orders`
QUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY amount DESC) = 1;

DECLARE min_amount INT64 DEFAULT 100;
SET min_amount = 200;
SELECT COUNT(*) AS cnt FROM `sales.orders` WHERE amount >= min_amount;
